impl RetryConfig {
    /// Returns the delay, in milliseconds, to wait before the retry that
    /// follows `failed_attempts` consecutive failures (0 = the first retry).
    ///
    /// The delay doubles for every additional failure and saturates at
    /// `max_delay_ms`. The computation uses saturating arithmetic, so even
    /// an extremely large exponent saturates without overflowing `u64`.
    pub fn retry_delay_ms(&self, failed_attempts: u32) -> u64 {
        let mut delay = self.base_delay_ms;
        for _ in 0..failed_attempts {
            delay = delay.saturating_mul(2).min(self.max_delay_ms);
            if delay == self.max_delay_ms {
                break;
            }
        }
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn delays_double_and_saturate() {
        let cfg = config(10, 10, 1000);
        assert_eq!(cfg.retry_delay_ms(0), 10);
        assert_eq!(cfg.retry_delay_ms(1), 20);
        assert_eq!(cfg.retry_delay_ms(2), 40);
        assert_eq!(cfg.retry_delay_ms(3), 80);
        assert_eq!(cfg.retry_delay_ms(4), 160);
        assert_eq!(cfg.retry_delay_ms(5), 320);
        assert_eq!(cfg.retry_delay_ms(6), 640);
        assert_eq!(cfg.retry_delay_ms(7), 1000);
        assert_eq!(cfg.retry_delay_ms(100), 1000);
    }

    #[test]
    fn huge_exponent_saturates_without_overflow() {
        let cfg = config(10, 1, u64::MAX);
        assert_eq!(cfg.retry_delay_ms(63), 1u64 << 63);
        assert_eq!(cfg.retry_delay_ms(64), u64::MAX);
        assert_eq!(cfg.retry_delay_ms(1_000_000), u64::MAX);
    }

