/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
///
/// Transient errors are retried with an exponential backoff that doubles
/// from `base_delay_ms` and saturates at `max_delay_ms`; permanent errors
/// abort immediately. `max_attempts` includes the first call.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut failed_attempts: u32 = 0;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                failed_attempts += 1;
                if failed_attempts >= config.max_attempts {
                    return Err(err);
                }
                let delay_ms = config.retry_delay_ms(failed_attempts - 1);
                sleeper.sleep_ms(delay_ms);
            }
        }
    }
}

